import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const FlaggedListings = () => {
  const [flagsByUser, setFlagsByUser] = useState({});
  const [users, setUsers] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/flagged`)
      .then((res) => res.json())
      .then((data) => {
        const grouped = data.reduce((acc, item) => {
          if (!acc[item.user_id]) acc[item.user_id] = [];
          acc[item.user_id].push(item);
          return acc;
        }, {});
        setFlagsByUser(grouped);
        setUsers(Object.keys(grouped));
      })
      .catch((err) => console.error("Error fetching flagged listings:", err));
  }, []);

  const handleUnflag = async (flagId) => {
    if (!window.confirm("Are you sure you want to remove this flag?")) return;
    const res = await fetch(`${API_BASE_URL}/api/flagged/${flagId}`, { method: "DELETE" });
    if (res.ok) window.location.reload();
    else alert("Failed to unflag.");
  };

  const handleBanUser = async (userId) => {
    if (!window.confirm(`Ban user #${userId}?`)) return;
    const res = await fetch(`${API_BASE_URL}/api/users/${userId}/ban`, { method: "POST" });
    if (res.ok) alert(`User #${userId} has been banned.`);
    else alert("Failed to ban user.");
  };

  const handleReview = async (flagId) => {
    const res = await fetch(`${API_BASE_URL}/api/flagged/${flagId}/reviewed`, { method: "POST" });
    if (res.ok) window.location.reload();
    else alert("Failed to mark as reviewed.");
  };

  return (
    <div className="dashboard-wrapper">
      <AdminNavbar />
      <main className="dashboard-main" style={{ minHeight: "100vh", padding: "32px 48px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>🚩 All Flagged Listings (Unreviewed Only)</h2>

        {users.length > 0 ? users.map(userId => (
          <div key={userId} style={{ marginBottom: "40px" }}>
            <h3>User #{userId}</h3>
            <button onClick={() => handleBanUser(userId)} className="flag-btn" style={{ marginBottom: "10px" }}>
              🚫 Ban User
            </button>
            <div className="item-grid">
              {flagsByUser[userId].map(item => (
                <div className="item-card" key={item.id}>
                  <div className="image-placeholder">
                    {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                  </div>
                  <h4>{item.title}</h4>
                  <p>{item.description}</p>
                  <p><strong>Condition:</strong> {item.condition}</p>
                  <p><strong>Reason:</strong> {item.reason}</p>
                  <p><strong>Total Flags:</strong> {item.total_flags}</p>
                  <label style={{ display: "block", marginTop: "10px" }}>
                    <input
                      type="checkbox"
                      checked={item.reviewed}
                      disabled={item.reviewed}
                      onChange={() => handleReview(item.id)}
                    />{" "}
                    Mark as Reviewed
                  </label>
                  <button onClick={() => handleUnflag(item.id)} className="delete-btn" style={{ marginTop: "10px" }}>
                    ❌ Unflag
                  </button>
                </div>
              ))}
            </div>
          </div>
        )) : (
          <p style={{ textAlign: "center" }}>No unreviewed flagged listings found.</p>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default FlaggedListings;
